import os, re, json

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_input = G['Demo pair 1 input']
test_input = G['Test input']

def solve(grid):
    """Solve the puzzle"""
    H, W = len(grid), len(grid[0])
    result = [[0]*W for _ in range(H)]

    # Find all 2x2 blocks
    blocks = []
    for r in range(H-1):
        for c in range(W-1):
            if grid[r][c]==2 and grid[r][c+1]==2 and grid[r+1][c]==2 and grid[r+1][c+1]==2:
                blocks.append((r,c))

    # Place all 2x2 blocks
    for br, bc in blocks:
        for dr in [0,1]:
            for dc in [0,1]:
                result[br+dr][bc+dc] = 2

    # Process special values
    for sr in range(H):
        for sc in range(W):
            val = grid[sr][sc]
            if val == 0 or val == 2:
                continue

            # Find nearest block center
            min_dist = float('inf')
            best_block = None
            for br, bc in blocks:
                cr, cc = br + 0.5, bc + 0.5
                dist = abs(sr - cr) + abs(sc - cc)
                if dist < min_dist:
                    min_dist = dist
                    best_block = (cr, cc)

            if not best_block:
                continue

            cr, cc = best_block

            # Determine diagonal type and direction based on parity and quadrant
            rel_r = sr - cr
            rel_c = sc - cc

            if val % 2 == 0:  # Even number -> main diagonal (diff constant)
                # Main diagonal extends along r-c = const
                # Direction depends on quadrant
                if rel_r <= 0 and rel_c >= 0:  # NE quadrant -> go SE (+,+)
                    d_row, d_col = 1, 1
                elif rel_r >= 0 and rel_c <= 0:  # SW quadrant -> go NW (-,-)
                    d_row, d_col = -1, -1
                else:
                    # Already on diagonal axis, go both ways? Just pick one consistently
                    if rel_r > rel_c:  # More in row direction
                        d_row, d_col = 1, 1
                    else:
                        d_row, d_col = -1, -1
            else:  # Odd number -> anti-diagonal (sum constant)
                # Anti-diagonal extends along r+c = const
                # Direction depends on quadrant
                if rel_r <= 0 and rel_c >= 0:  # NE quadrant -> go NE (-,+)? Actually need r+c const
                    # For anti-diag going NE, we decrease r, increase c
                    d_row, d_col = -1, 1
                elif rel_r >= 0 and rel_c <= 0:  # SW quadrant -> go SW (+,-)
                    d_row, d_col = 1, -1
                else:
                    if rel_r > 0:
                        d_row, d_col = 1, -1
                    else:
                        d_row, d_col = -1, 1

            # Extend along diagonal from (sr, sc)
            rr, ccl = sr, sc
            while True:
                rr += d_row
                ccl += d_col
                if 0 <= rr < H and 0 <= ccl < W and result[rr][ccl] == 0:
                    result[rr][ccl] = val
                else:
                    break

    return result

