    result = [[0]*W for _ in range(H)]

    # Place blocks first (so fills don't overwrite them)
    block_cells = set()
    for r in range(H-1):
        for c in range(W-1):
            if grid[r][c]==2 and grid[r][c+1]==2 and grid[r+1][c]==2 and grid[r+1][c+1]==2:
                for dr in [0,1]:
                    for dc in [0,1]:
                        block_cells.add((r+dr, c+dc))
                        result[r+dr][c+dc] = 2

    mid_r = H/2
    target_sum_anti = (H+W)//2 - 1  # e.g., 7 for 9x9

    special_vals = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v in [3, 6, 7, 8]:
                special_vals[(r,c)] = v

    for pos, val in special_vals.items():
        sr, sc = pos
        use_main = (val % 2 == 0)

