            if sr < mid_r:
                # Fill towards BOTTOM-RIGHT (higher indices)
                # Start somewhere in the top-half diagonal segment
                # Looking at demo: value 6 at row 2 starts at row 5
                start_row = max(int(mid_r * 2), 5)  # At least row 5, or row ~mid*2
            else:
                # Fill towards TOP-LEFT (lower indices)
                start_row = 0

            rr, cc = start_row, start_row
            d_r, d_c = 1, 1

            steps = 0
            while 0 <= rr < H and 0 <= cc < W and (rr,cc) not in block_cells and result[rr][cc] == 0:
                result[rr][cc] = val
                rr += d_r
                cc += d_c
                steps += 1
                if steps > 10: break

        else:
            # Anti-diagonal: r+c=target_sum
            if sr < mid_r:
                # Fill towards TOP-RIGHT (high column / low row)
                # Start from rightmost valid cell on anti-diag
                start_col = min(W-1, target_sum_anti)
                start_row = target_sum_anti - start_col
            else:
                # Fill towards BOTTOM-LEFT (low column / high row)  
                start_col = max(0, target_sum_anti - int(mid_r))
                start_row = target_sum_anti - start_col

            # Ensure bounds
            if not (0 <= start_row < H and 0 <= start_col < W):
                start_col = target_sum_anti
                if 0 <= target_sum_anti < W:
                    start_row = 0
                else:
                    start_row = target_sum_anti - (target_sum_anti if target_sum_anti < W else W-1)

            d_r, d_c = 1, -1  # SW direction for filling
            steps = 0
            while 0 <= rr < H and 0 <= cc < W and (rr,cc) not in block_cells and result[rr][cc] == 0:
                result[rr][cc] = val
                rr += d_r
                cc += d_c
                steps += 1
                if steps > 10: break

    return result

